#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <inttypes.h>

#define MAX_VALUE 0xBFA17DC6ULL   /* 3215031750 */

static uint64_t mul_mod(uint64_t a, uint64_t b, uint64_t mod)
{
    __uint128_t res = ( __uint128_t ) a * b;
    return (uint64_t)(res % mod);
}

static uint64_t pow_mod(uint64_t base, uint64_t exp, uint64_t mod)
{
    uint64_t result = 1 % mod;
    base %= mod;
    while (exp) {
        if (exp & 1)
            result = mul_mod(result, base, mod);
        base = mul_mod(base, base, mod);
        exp >>= 1;
    }
    return result;
}

static int is_prime(uint64_t n)
{
    if (n < 2)
        return 0;
    uint64_t d = n - 1;
    unsigned int s = 0;
    while ((d & 1) == 0) {
        d >>= 1;
        ++s;
    }
    const uint64_t bases[] = {2, 3, 5, 7, 11, 13};
    for (size_t i = 0; i < sizeof(bases)/sizeof(bases[0]); ++i) {
        uint64_t a = bases[i];
        if (a >= n)
            break;
        uint64_t x = pow_mod(a, d, n);
        if (x == 1 || x == n - 1)
            continue;
        int composite = 1;
        for (unsigned int r = 1; r < s; ++r) {
            x = mul_mod(x, x, n);
            if (x == n - 1) {
                composite = 0;
                break;
            }
        }
        if (composite)
            return 0;
    }
    return 1;
}

int main(int argc, char **argv)
{
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr = NULL;
    long long val = strtoll(argv[1], &endptr, 10);
    if (endptr == argv[1]) {
        puts("BAD_INPUT");
        return 0;
    }
    if ((uint64_t)val > MAX_VALUE) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    if (is_prime((uint64_t)val))
        puts("PRIME");
    else
        puts("NOT_PRIME");
    return 0;
}
